class _S extends State<WatchCenterScreen>{@override Widget build(BuildContext c){final active=widget.store.watch.where((x)=>x.active).toList();return Scaffold(appBar:AppBar(title:const Text('Watch center')),body:active.isEmpty?const Center(child:Text('No active watch items')):ListView(padding:const EdgeInsets.all(12),children:active.map((w)=>Card(child:ListTile(leading:const Icon(Icons.visibility,color:OperonTheme.teal),title:Text(w.equipmentTag??w.title),subtitle:Text(w.title+' · '+w.detail),trailing:IconButton(icon:const Icon(Icons.check_circle_outline),onPressed:(){widget.store.resolveWatch(w);setState((){});}))).toList()));}}
